import{z as s,x as i,o as e,c as p,q as B,j as t,D as E,d as A,s as r,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"俱乐部物品","description":"","frontmatter":{"title":"俱乐部物品","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/club-goods.md","filePath":"econ/club-goods.md","lastUpdated":1791413859000}'),d={name:"econ/club-goods.md"};function C(c,a,m,u,h,D){const o=i("Mermaid");return e(),p("div",null,[a[2]||(a[2]=B('<h1 id="俱乐部物品" tabindex="-1">俱乐部物品 <a class="header-anchor" href="#俱乐部物品" aria-label="Permalink to &quot;俱乐部物品&quot;">​</a></h1><div class="epigraph"><p>一种可以排他、却会因人数拥挤的商品：会费分摊固定成本，最优俱乐部规模在分摊与拥挤之间切一刀。</p><footer>—— 据 Buchanan, An Economic Theory of Clubs, Economica, 1965 整理</footer></div><p><a href="/econ/public-goods">上一课</a>（公共物品与免费搭车）。纯公共品非竞争又非排他，\\(\\sum\\mathrm{MRS}=\\mathrm{MRT}\\)，自愿贡献免费搭车。本课不重写萨缪尔森加总，也不把 Lindahl 价再列一遍。缺口是中间形态：围墙能立住（排他），但容量内越来越挤（部分竞争）。Buchanan 的俱乐部把「谁进来、规模多大」写成选择，而不是全人口强制消费同一 \\(G\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯公共品：\\(n\\) 增加不降每人的 \\(G\\)，又赶不走不付费者。俱乐部：设施 \\(X\\) 可排他，效用 \\(u(x,n)\\)，\\(n\\) 升则拥挤，\\(u\\) 对 \\(n\\) 下降。固定成本 \\(C(X)\\) 由会员分摊，会费 \\(c=C(X)/n\\)。最优要同时选设施规模与人数。缺口不是再骂免费搭车，而是：<strong>排他恢复之后，最优 \\(n\\) 从哪来，以及为何「整个经济一个俱乐部」一般不是解。</strong></p><p>共享的好处是摊薄 \\(C\\)；坏处是拥挤。一阶条件：新会员带来的会费下降，应等于他加在全体身上的边际拥挤。设施的边际成本应等于会员边际评价之和——在俱乐部内部像一条迷你萨缪尔森条件，但 \\(n\\) 是内生的。</p><p><span class="marginnote">术语翻译：俱乐部物品就是「能收门票、但人多会挤」的共享设施——健身房、小区泳池、收费公路、视频会员库。它能排他（不交钱进不来），又不完全竞争（会员再多一个，大家的体验就差一点），恰好卡在纯公共品与纯私人品之间。</span></p><h3 id="排他把免费搭车切掉一块" tabindex="-1">排他把免费搭车切掉一块 <a class="header-anchor" href="#排他把免费搭车切掉一块" aria-label="Permalink to &quot;排他把免费搭车切掉一块&quot;">​</a></h3><p>能收费，自愿贡献博弈换成「进不进这个俱乐部」。仍可能有许多俱乐部竞争（Tiebout 用脚投票是后话），本课先钉单一俱乐部的最优规模。不能排他时，Buchanan 的会费收不上来，退回上一课。</p><p><span class="marginnote">Buchanan 1965 的图：横轴是 \\(n\\)，纵轴是人均净收益。最优 \\(n^*\\) 在人均收益最大处，不是「越大越好」。纯公共品是拥挤为零的极限，\\(n^*\\) 趋于全体；纯私人品是拥挤极陡，\\(n^*=1\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>代表性会员，对称分享。规划：\\(\\max_{X,n} u\\bigl(X,n\\bigr)\\) s.t. 人均成本 \\(C(X)/n\\)（或把预算写进 \\(u\\) 的私人品）。两个一阶条件分别钉 \\(X\\) 与 \\(n\\)。人口很大、可复制俱乐部时，均衡是许多个规模为 \\(n^*\\) 的俱乐部，像长期进入把厂商钉在有效规模——对照<a href="/econ/long-run-entry">长期进入</a>，这里复制的是设施加会员包。</p><p>非对称偏好：不同 \\(\\theta\\) 想要不同 \\(X\\) 与 \\(n\\)，混合俱乐部有拥挤外部性与排序成本，分层（高需求者自己一组）往往更稳。本课对称教具已够把「内生 \\(n\\)」钉住。会费必须能排除不付费者；排他技术一垮，退回上一课的自愿贡献。</p>',13)),(e(),t(l,null,{default:E(()=>[r(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUB%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E4%B8%8D%E8%83%BD%E6%8E%92%EF%BC%8C%CE%A3%20MRS%20%3D%20MRT%22%5D%20--%3E%20CLUB%5B%22%E8%83%BD%E6%8E%92%E3%80%81%E4%BC%9A%E6%8B%A5%E6%8C%A4%22%5D%0A%20%20CLUB%20--%3E%20N%5B%22%E6%9C%80%E4%BC%98%20n%EF%BC%9A%E6%91%8A%E8%96%84%20vs%20%E6%8B%A5%E6%8C%A4%22%5D%0A%20%20CLUB%20--%3E%20X%5B%22%E8%AE%BE%E6%96%BD%EF%BC%9A%E4%BC%9A%E5%91%98%E5%86%85%E9%83%A8%E5%8A%A0%E6%80%BB%20MRS%22%5D%0A%20%20N%20--%3E%20REP%5B%22%E5%8F%AF%E5%A4%8D%E5%88%B6%EF%BC%9A%E8%AE%B8%E5%A4%9A%E4%B8%AA%20n*%20%E4%BF%B1%E4%B9%90%E9%83%A8%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"不要把会费写成商品税。会费是排他装置，不付则进不去；Ramsey 税是对已经在市场上的私人品钉楔子。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[A("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"内生 \\(n\\) 的机制是拥挤与分摊的对冲：第 \\(n+1\\) 人降低人均固定成本，也降低每人的 \\(u\\)。切点就是俱乐部的「有效规模」。排他的机制是把非会员的 MRS 从加总里拿掉——他们不享用 \\(X\\)，萨缪尔森加总只在会员里做。这与纯公共品「必须加总全人口」正好相反。",-1)),(e(),t(l,null,{default:E(()=>[r(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADD%5B%22%E5%A4%9A%E6%94%B6%E4%B8%80%E5%90%8D%E4%BC%9A%E5%91%98%22%5D%20--%3E%20GAIN%5B%22%E5%A5%BD%E5%A4%84%EF%BC%9A%E4%BA%BA%E5%9D%87%E4%BC%9A%E8%B4%B9%20C(X)%2Fn%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20ADD%20--%3E%20PAIN%5B%22%E5%9D%8F%E5%A4%84%EF%BC%9A%E5%85%A8%E4%BD%93%E7%8E%B0%E6%9C%89%E4%BC%9A%E5%91%98%E6%9B%B4%E6%8B%A5%E6%8C%A4%22%5D%0A%20%20GAIN%20--%3E%20CMP%5B%22%E9%80%90%E4%B8%AA%E6%AF%94%E8%BE%83%EF%BC%9A%E7%9C%81%E4%B8%8B%E7%9A%84%E4%BC%9A%E8%B4%B9%20vs%20%E5%8A%A0%E6%80%BB%E7%9A%84%E6%8B%A5%E6%8C%A4%22%5D%0A%20%20PAIN%20--%3E%20CMP%0A%20%20CMP%20--%3E%20STAR%5B%22%E4%BA%8C%E8%80%85%E7%9B%B8%E7%AD%89%E5%A4%84%20%3D%20%E6%9C%80%E4%BC%98%E8%A7%84%E6%A8%A1%20n*%22%5D%0A%20%20STAR%20--%3E%20LIM1%5B%22%E6%8B%A5%E6%8C%A4%E6%9E%81%E9%99%A1%20%E2%86%92%20n*%3D1%EF%BC%9A%E7%BA%AF%E7%A7%81%E4%BA%BA%E5%93%81%22%5D%0A%20%20STAR%20--%3E%20LIM2%5B%22%E6%8B%A5%E6%8C%A4%E4%B8%BA%E9%9B%B6%20%E2%86%92%20n*%3D%E5%85%A8%E4%BD%93%EF%BC%9A%E7%BA%AF%E5%85%AC%E5%85%B1%E5%93%81%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">数字实例：泳池造价 100 万元。50 人分摊，人均 2 万元；500 人分摊，人均降到 2000 元——但排队时间也涨了十倍。最优规模 \\(n^*\\) 停在「再拉一个人省下的会费，恰好抵不上全体多忍受的拥挤」那一点；过了这个点，更大的俱乐部人人吃亏。</span></p><p>可复制的机制与 U 形 AC 同一：单个设施有最优容量，经济靠开新俱乐部扩张，而不是把一个游泳池无限挤进去。IRS 若强到整个经济只能有一个设施，俱乐部理论碰到自然垄断，会费变成规制问题。</p><p>非对称会员：高拥挤敏感者愿为低 \\(n\\) 付更高会费，分层俱乐部把不同 \\(\\theta\\) 分开，类似纵差异的质量阶梯，但这里分的是容量而不是 \\(s\\)。强制开放入会把 \\(n\\) 推过 \\(n^*\\)，人均净收益下降——排他不是天然的恶，它是最优规模的工具。</p><p><span class="marginnote">地方公共品、社区、协会是经验对应。Buchanan 的理论不保证自愿俱乐部达到全球帕累托：排除在外的人可能仍有正评价，只是低于会费。全局有效还要问这些人能否另组俱乐部。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>拥挤若对 \\(n\\) 不可微，最优规模可以停在整数区间。</p><p><span class="marginnote">常见误区：把「收费、排他」一律当成对穷人的恶意或市场的堕落。在俱乐部框架里，会费首先是把规模钉在 \\(n^*\\) 的工具：没有排他，拥挤会把人均净收益拖下水；强制无限开放，反而让设施过度拥挤甚至无法维持。排他是否正当，要看它服务的是效率还是排斥。</span></p><p>Tiebout 用管辖竞争显示偏好，下一课之后的林达尔也不代替用脚投票：那是许多俱乐部（社区）竞争，把 Buchanan 的 \\(n^*\\) 乘上辖区数目。反歧视、开放入会规则会把 \\(n\\) 的选择从俱乐部手中拿走。下一课<a href="/econ/common-pool">公地</a>取另一极：很难排他、但消费可分——拥挤变成捕获，会费收不上。</p><p>后课默认：俱乐部是可排他、拥挤的共享；最优规模在摊薄与拥挤之间；纯公共品与纯私人品是 \\(n\\) 的两个极限。</p><p>本课不把会费写成 Ramsey 税。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>排他恢复后，免费搭车换成入会决策。</li><li>最优 \\(n\\) 平衡人均成本下降与边际拥挤。</li><li>设施规模在会员内部满足加总 MRS。</li><li>下一课：不能排他却可分的资源，捕获替代会费。</li><li>出处：Buchanan, <em>Economica</em>, 1965。</li></ul>',12))])}const _=s(d,[["render",C]]);export{f as __pageData,_ as default};
